local EXPECTED_ASSEMBLED_DIGEST = "ffebd7bce9587f1f70a81f365e7b6f349db29bd82d964b5e9c6b8f812f4f41e2"
local partManifest = {
  { name = [[01.part]], bytes = 11986, digest = [[acfe083dbc386cba2100e64fa59db1ed967911ea49f1304f223caab8d72b6cdf]] },
  { name = [[02.part]], bytes = 11990, digest = [[79f47d721be396b6b863cb859606bc131485e1488f8adc7530cd541696c760a4]] },
  { name = [[03.part]], bytes = 11976, digest = [[039d083ca0d9c9fb86df3cce6557894165620851ca7d6c7c0a6d4e3a33b03b9a]] },
  { name = [[04.part]], bytes = 11971, digest = [[41e0a87e40546036a976c6acb1fa87fbb2a883345a43510619c9ee33349fdc93]] },
  { name = [[05.part]], bytes = 11965, digest = [[7820b8d6520497580e302b2733d4ad7fefa484380843dab4d23cb58b500aa745]] },
  { name = [[06.part]], bytes = 11991, digest = [[3663a82e1e6e95530cbece438d27d5b81ef25303adfe1910c14f6c9e370d0ea1]] },
