  { name = [[09.part]], bytes = 11894, digest = [[b10ff323bf39a7eea99f6e9a7b97657913894f1a44d2e72e54fe59bc369ba4cf]] },
  { name = [[10.part]], bytes = 11958, digest = [[40557d03618cedc68bc9bda6599c26540a2fdf8059714a3c42141dbde62ef539]] },
  { name = [[11.part]], bytes = 11967, digest = [[2a06b979f0f0e32079d0f322a9f5919325d8209d0f5ff187f89176b6a46f263c]] },
  { name = [[12.part]], bytes = 11998, digest = [[4afcddb425a622ec1659ce6111681d7c30c4b7a322ca478ebad6c6e04637f12c]] },
  { name = [[13.part]], bytes = 11990, digest = [[2a0ad40dc736f108547671f15ed909ac36e180fb15c607af765b1fb0e2a4f940]] },
